import {normalizeRoom,moveRoomTarget,wallFrame,furnitureNames,officeChairPlacement} from './room.js?v=9-office-chair';
import {roomControls,roomItem,roomValue,escapeHTML} from './room-editor.js?v=9-office-chair';
import {defaults,presets,fields,clamp,round,evaluate,sanitize,layoutPreset,desktopTargets,placeDeskItem,updateDeskItem,clampEdge,deskBounds,fieldSpec,resizeDesk,editArm,moveArmJoint,wrapAngle} from './model.js?v=9-office-chair';
import {CockpitScene} from './scene.js?v=9-office-chair';

const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const paths={
 lock:'M6 9V6a3 3 0 0 1 6 0v3M4 9h10v7H4z',export:'M10 3h5v5M15 3 8 10M6 4H3v11h11v-3',download:'M9 2v10m-4-4 4 4 4-4M3 13v3h12v-3',upload:'M9 12V2m-4 4 4-4 4 4M3 13v3h12v-3',wheel:'M15.5 9A6.5 6.5 0 1 1 2.5 9a6.5 6.5 0 0 1 13 0ZM3 7l4 1 2 6 2-6 4-1M7 8h4',frame:'M3 14V4h12v10M1 14h16M7 4v10M11 4v10M3 8h12',seat:'M5 2v7l4 3h6v3H8l-5-4V3M7 15v2m7-2v2M12 4v5h4',desk:'M2 5h14v3H2zM4 8v8m10-8v8M4 12h10',help:'M9 16A7 7 0 1 0 9 2a7 7 0 0 0 0 14ZM7 6a2 2 0 1 1 3 2c-1 1-1 1-1 2M9 13h.01',reset:'M3 6a6 6 0 1 1-1 5M3 2v4h4',ruler:'M2 13 13 2l3 3L5 16ZM5 10l2 2m1-5 2 2m1-5 2 2',person:'M11.5 4a2.5 2.5 0 1 1-5 0 2.5 2.5 0 0 1 5 0ZM4 16v-4a5 5 0 0 1 10 0v4',expand:'M6 2H2v4m10-4h4v4M2 12v4h4m6 0h4v-4',rotate:'M3 6a6 6 0 1 1 0 7M3 2v4h4M9 5v8m-3-4h6',info:'M9 16A7 7 0 1 0 9 2a7 7 0 0 0 0 14ZM9 8v5M9 5h.01',parts:'M3 3h5v5H3zm7 7h5v5h-5zM3 10h5v5H3zm7-7h5v5h-5z',arrow:'M3 9h12m-5-5 5 5-5 5',close:'m4 4 10 10M14 4 4 14',print:'M5 6V2h8v4M5 13H2V7h14v6h-3M5 10h8v6H5zM13 8h.01'
};
function icons(root=document){root.querySelectorAll('i[data-icon]').forEach(i=>i.innerHTML=`<svg viewBox="0 0 18 18" aria-hidden="true"><path d="${paths[i.dataset.icon]||paths.info}"/></svg>`);}
icons();
const KEY='cockpit-lab-v1';let state={...defaults},section='rig',view='iso',modified=false,scene,layoutTarget='desk',layoutEditing=false;
try{const saved=localStorage.getItem(KEY);if(saved)state=sanitize(JSON.parse(saved).config);}catch{}
let evaluation=evaluate(state);
let pendingSave,toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify({version:1,config:state}));$('#saveStatus').textContent='Guardado en este navegador';}catch{$('#saveStatus').textContent='Guardado automático no disponible';}}
function update(key,value){state=updateDeskItem(editArm(state,key,value),key,value);if(key.startsWith('room'))state=normalizeRoom(state);modified=true;$('#saveStatus').textContent='Guardando…';clearTimeout(pendingSave);pendingSave=setTimeout(persist,250);refresh();}
const unitFor=k=>k==='monitorInches'?'″':k==='armSplit'?'%':(['recline','wheelTilt','pedalTilt','monitorYaw'].includes(k)||k.endsWith('Angle'))?'°':'cm';
function controlValue(key){return key==='armBaseAngle'?evaluation.armPose.baseAngle:key==='armElbowAngle'?evaluation.armPose.elbowAngle:key==='monitorYaw'?wrapAngle(evaluation.monitorAngle-state.deskAngle):state[key];}
function range(key,label){const [min,max,step]=fieldSpec(key,state),value=round(controlValue(key),1);return `<div class="control"><div class="control-top"><label for="${key}-range">${label}</label><div class="number-wrap"><input id="${key}-number" type="number" data-key="${key}" data-number min="${min}" max="${max}" step="${step}" value="${value}" aria-label="${label}, valor en ${unitFor(key)}"><span>${unitFor(key)}</span></div></div><input id="${key}-range" type="range" data-key="${key}" min="${min}" max="${max}" step="${step}" value="${value}" aria-label="${label}" style="--pct:${(value-min)/(max-min)*100}%"><div class="control-range-label"><span>${min}</span><span>${max} ${unitFor(key)}</span></div></div>`;}
function toggle(key,label){return `<div class="toggle-control"><label for="${key}">${label}</label><label class="switch"><input type="checkbox" id="${key}" data-key="${key}" ${state[key]?'checked':''} aria-label="${label}"><span class="switch-track"></span></label></div>`;}
function select(key,label,options){return `<div class="select-control"><label for="${key}">${label}</label><select id="${key}" data-key="${key}">${options.map(([value,text])=>`<option value="${value}" ${state[key]===value?'selected':''}>${text}</option>`).join('')}</select></div>`;}
const group=(title,html,hint='')=>`<div class="control-group"><h3 class="group-title">${title}${hint?`<span>${hint}</span>`:''}</h3>${html}</div>`;
function roomChanged(redraw=false){state=normalizeRoom(state);modified=true;clearTimeout(pendingSave);pendingSave=setTimeout(persist,250);if(redraw)renderControls();refresh();}
function selectRoomTarget(target){layoutTarget=target;layoutEditing=true;$('#layoutBtn').classList.add('active');$('#layoutBtn').setAttribute('aria-pressed','true');renderControls();scene?.setLayoutEditing(true,target,true);setActiveView('top');}
function changeRoomValue(key,value,redraw=false){
 const item=roomItem(state,layoutTarget);
 if(item){const list=item.wall?'roomFeatures':'roomFurniture';const adjusted=key==='x'?value+state.roomX:key==='z'?value+state.roomZ:value;state={...state,[list]:state[list].map(v=>v.id===item.id?{...v,[key]:adjusted}:v)};}
 else if(['desk','cockpit'].includes(layoutTarget)){if(key==='x')state[layoutTarget+'X']=value+state.roomX;else if(key==='z')state[layoutTarget+'Z']=value+state.roomZ;else if(key==='angle')state[layoutTarget+'Angle']=value;}
 roomChanged(redraw);
}
function syncRoomInputs(){if(section!=='room')return;const item=roomItem(state,layoutTarget),frame=item?.wall?wallFrame(state,item.wall):null;$('#controls').querySelectorAll('[data-room-key]').forEach(el=>{const key=el.dataset.roomKey,value=roomValue(state,layoutTarget,key);if(['number','range'].includes(el.type)){const limits=key==='offset'&&frame?[0,frame.length-item.width]:key==='width'&&frame?[30,Math.min(300,frame.length)]:key==='height'&&frame?[30,state.roomH]:key==='sill'&&frame?[0,state.roomH-item.height]:key==='x'?[-200,state.roomW+200]:key==='z'?[-200,state.roomD+200]:null;if(limits){el.min=limits[0];el.max=limits[1];}}if(el!==document.activeElement&&value!==undefined)el.value=value;if(el.type==='range')el.style.setProperty('--pct',`${(Number(el.value)-Number(el.min))/(Number(el.max)-Number(el.min)||1)*100}%`);});}

function bindRoomEditor(){
 $('#roomTarget')?.addEventListener('change',event=>selectRoomTarget(event.target.value));
 $('#controls').querySelectorAll('[data-room-key]').forEach(el=>{
  if(el.tagName==='SELECT'){el.addEventListener('change',()=>changeRoomValue(el.dataset.roomKey,el.value,true));return;}
  if(el.type!=='number'&&el.type!=='range'){el.addEventListener('change',()=>changeRoomValue(el.dataset.roomKey,el.value,true));return;}
  const apply=commit=>{if(el.value.trim()===''||!Number.isFinite(Number(el.value)))return;const raw=Number(el.value);if(!commit&&(raw<Number(el.min)||raw>Number(el.max)))return;const value=round(clamp(raw,Number(el.min),Number(el.max)),1);changeRoomValue(el.dataset.roomKey,value,false);if(commit){el.value=roomValue(state,layoutTarget,el.dataset.roomKey);if(['width','height'].includes(el.dataset.roomKey))renderControls();}};
  el.addEventListener('input',()=>apply(false));el.addEventListener('change',()=>apply(true));
 });
 $('#controls').querySelectorAll('[data-room-rotate]').forEach(el=>el.addEventListener('click',()=>changeRoomValue('angle',(roomValue(state,layoutTarget,'angle')+Number(el.dataset.roomRotate)+360)%360)));
 $('#controls').querySelectorAll('[data-add-room]').forEach(el=>el.addEventListener('click',()=>{
  const type=el.dataset.addRoom,id=crypto.randomUUID?.()||'room-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,9),opening=['door','window'].includes(type);if(opening&&state.roomFeatures.length>=24||!opening&&state.roomFurniture.length>=30){toast('Límite de elementos alcanzado');return;}
  if(opening){state={...state,roomFeatures:[...state.roomFeatures,{id,type,name:type==='door'?'Puerta':'Ventana',wall:type==='door'?'south':'north',offset:type==='door'?20:Math.max(0,(state.roomW-120)/2),width:type==='door'?80:120,height:type==='door'?205:120,sill:type==='door'?0:100,hinge:'start',swing:'in',openAngle:90,clearance:60}]};}
  else if(type==='chair'){const chair={id,type,name:'Silla de PC',width:65,depth:65,height:115,seatHeight:47,pullback:50};state={...state,roomFurniture:[...state.roomFurniture,{...chair,...officeChairPlacement(state,chair)}]};}
  else state={...state,roomFurniture:[...state.roomFurniture,{id,type,name:furnitureNames[type],x:state.roomX+state.roomW/2,z:state.roomZ+state.roomD/2,width:80,depth:type==='wardrobe'?55:35,height:type==='wardrobe'?200:180,angle:0}]};
  state.roomEnabled=true;state=normalizeRoom(state);layoutTarget=(opening?'feature:':'furniture:')+id;roomChanged(true);selectRoomTarget(layoutTarget);toast(opening?'Hueco añadido. Ajusta su pared y medidas.':'Mueble añadido. Arrástralo en planta.');
 }));
 $('#chairAtDesk')?.addEventListener('click',()=>{const item=roomItem(state,layoutTarget);if(item?.type!=='chair')return;state={...state,roomFurniture:state.roomFurniture.map(v=>v.id===item.id?{...v,...officeChairPlacement(state,v)}:v)};roomChanged(true);scene?.setLayoutEditing(layoutEditing,layoutTarget,true);setActiveView('top');toast('Silla colocada frente al escritorio');});
 $('#roomDelete')?.addEventListener('click',()=>{const item=roomItem(state,layoutTarget);if(!item)return;const list=item.wall?'roomFeatures':'roomFurniture';state={...state,[list]:state[list].filter(v=>v.id!==item.id)};layoutTarget='desk';roomChanged(true);scene?.setLayoutEditing(layoutEditing,layoutTarget,true);toast('Elemento eliminado');});
 $('#roomFrame')?.addEventListener('click',()=>{setActiveView('top');});
 $('#roomCenter')?.addEventListener('click',()=>{const e=evaluation,dx=state.roomX+state.roomW/2-(e.allLeft+e.allRight)/2,dz=state.roomZ+state.roomD/2-(e.allBack+e.allFront)/2;state={...state,deskX:round(state.deskX+dx),deskZ:round(state.deskZ+dz),cockpitX:round(state.cockpitX+dx),cockpitZ:round(state.cockpitZ+dz)};roomChanged(true);setActiveView('top');toast('Mesa y cockpit centrados conservando su distribución');});
}
function roomSummary(s){if(s.roomEnabled===false)return '';const a=escapeHTML;return `<h3 class="summary-title">Habitación y obstáculos<span>Medidas en cm</span></h3><table class="summary-table"><thead><tr><th>Elemento</th><th>Ubicación</th><th>Medidas / apertura</th></tr></thead><tbody>${s.roomFeatures.map(v=>`<tr><td>${a(v.name)}</td><td>Pared ${wallFrame(s,v.wall).corner} · inicio ${v.offset}</td><td>${v.width} × ${v.height} · ${v.type==='door'?v.openAngle+'° '+(v.swing==='in'?'interior':'exterior'):'antepecho '+v.sill+' · reserva '+v.clearance}</td></tr>`).join('')}${s.roomFurniture.map(v=>`<tr><td>${a(v.name)}</td><td>X ${round(v.x-s.roomX)} / Z ${round(v.z-s.roomZ)} · ${v.angle}°</td><td>${v.width} × ${v.depth} × ${v.height}${v.type==='chair'?` · asiento ${v.seatHeight} · retirada ${v.pullback}`:''}</td></tr>`).join('')}</tbody></table>`;}
function renderControls(){
 let html='';
 if(section==='rig'){
  html+=group('Base de aluminio',range('length','Largo del chasis')+range('width','Ancho exterior'),'40 × 80 / 40 × 40');
  html+=group('Módulos y mandos',toggle('wheel','Volante y base DD')+toggle('hotas','HOTAS lateral')+toggle('centerStick','Joystick central')+toggle('shifter','Cambio en H')+toggle('handbrake','Freno de mano')+select('drivingSide','Lado del cambio y freno',[['right','Derecha del piloto'],['left','Izquierda del piloto']])+select('feet','Apoyo',[['level','Pies niveladores'],['casters','Ruedas con freno']]));
  html+='<p class="control-hint">Derecha e izquierda del cambio y freno se miran sentado al volante. Chasis fijo y módulos desmontables. El ancho total incluye los accesorios activos. La selección de perfiles es preliminar; no calcula rigidez para tu base DD.</p>';
 }else if(section==='body'){
  html+=group('Tu punto de partida',range('height','Tu estatura'));
  html+=group('Asiento',range('seatZ','Posición longitudinal')+range('seatH','Altura del cojín')+range('recline','Reclinación del respaldo'),'Desde atrás / suelo');
  if(state.wheel)html+=group('Volante',range('wheelZ','Posición longitudinal')+range('wheelH','Altura del centro')+range('wheelTilt','Inclinación de la base'));
  html+=group('Pedalera',range('pedalZ','Posición longitudinal')+range('pedalH','Altura de plataforma')+range('pedalTilt','Inclinación de plataforma'));
  if(state.hotas||state.shifter||state.handbrake)html+=group('Mandos laterales',range('hotasZ','Posición longitudinal')+range('hotasH','Altura de las placas')+range('hotasOut','Salida desde el chasis'));
  if(state.centerStick)html+=group('Joystick central',range('stickZ','Posición longitudinal')+range('stickH','Altura de la placa'));
  html+='<p class="control-hint">Las posiciones parten del extremo trasero del chasis y las alturas, del suelo. Reclinar se mide desde la vertical. Activa el piloto para explorar la postura.</p>';
 }else if(section==='room'){
  html=roomControls(state,evaluation,layoutTarget,range,toggle);
 }else{
  const size=`${state.deskWidth}x${state.deskDepth}`;
  html+=group('Tablero de la mesa',`<div class="select-control"><label for="deskSizePreset">Medida rápida</label><select id="deskSizePreset"><option value="custom">Personalizada</option>${['120x60','120x80','140x60','140x80','160x80','180x80','200x80'].map(value=>`<option value="${value}" ${value===size?'selected':''}>${value.replace('x',' × ')} cm</option>`).join('')}</select></div>`+range('deskWidth','Ancho del tablero')+range('deskDepth','Fondo del tablero')+'<p class="layout-hint">Ancho × fondo. Los objetos conservan su tamaño y se recolocan dentro del tablero cuando caben. Los pies de referencia mantienen 66 cm de fondo.</p>','Ancho × fondo');
  html+=group('Monitor y brazo articulado',`<div class="arm-shortcuts"><button data-monitor-pose="cockpit">Llevar al cockpit</button><button data-monitor-pose="desk">Llevar al escritorio</button></div>`+select('monitorMode','Posición del monitor',[['cockpit','Frente al cockpit'],['desk','Sobre escritorio'],['vr','VR · aparcado'],['manual','Articulaciones manuales']])+`<button class="arm-edit-action" id="armDragBtn">Editar articulaciones en planta ↗</button>`+range('armBaseAngle','Giro de la base')+range('armElbowAngle','Flexión del codo')+range('monitorYaw','Giro de la pantalla (VESA)')+select('armBend','Lado de flexión',[['positive','Codo hacia un lado'],['negative','Codo hacia el otro']])+range('monitorH','Altura centro VESA')+range('monitorAhead','Pantalla delante volante')+range('monitorInches','Diagonal de pantalla')+'<p class="layout-hint">Arrastra <b>CODO</b> para girar el primer tramo o <b>VESA</b> para mover el extremo. Los controles de giro activan el modo manual. Los botones de colocación vuelven a calcular la postura hacia el destino.</p>').replace('<div class="control-group">','<div class="control-group" id="armControls">');
  html+=group('Medidas del brazo',range('armReach','Longitud total de los tramos')+range('armSplit','Primer tramo (% del total)')+`<p class="layout-hint" id="armLengths">Primer tramo: ${round(evaluation.armPose.first)} cm · segundo tramo: ${round(evaluation.armPose.second)} cm. El codo a 0° deja el brazo estirado; ±180° lo pliega.</p>`+range('armMinH','Altura VESA mínima')+range('armMaxH','Altura VESA máxima'),'Modelo genérico de 2 tramos');
  const item=desktopTargets.find(t=>t.id===layoutTarget),prefix=item?item.prefix:layoutTarget;
  const picker=`<div class="select-control target-picker"><label for="layoutTargetSelect">Elemento a mover</label><select id="layoutTargetSelect"><optgroup label="Distribución del espacio"><option value="cockpit" ${layoutTarget==='cockpit'?'selected':''}>Cockpit</option><option value="desk" ${layoutTarget==='desk'?'selected':''}>Escritorio completo</option></optgroup><optgroup label="Sobre el tablero">${desktopTargets.map(t=>`<option value="${t.id}" ${layoutTarget===t.id?'selected':''}>${t.label}</option>`).join('')}</optgroup></select></div>`;
  let placement='';
  if(layoutTarget==='arm'){
   placement+=select('clampMount','Fijación',[['clamp','Mordaza al borde'],['grommet','Pasante / taladro']]);
   if(state.clampMount==='clamp'){const edge=clampEdge(state);placement+=`<div class="select-control"><label for="clampEdgeSelect">Borde del tablero</label><select id="clampEdgeSelect">${[['xmin','Trabajo (−X)'],['xmax','Posterior (+X)'],['zmin','Extremo −Z'],['zmax','Extremo +Z']].map(([value,label])=>`<option value="${value}" ${edge===value?'selected':''}>${label}</option>`).join('')}</select></div>`+range(edge[0]==='x'?'clampZ':'clampX','Posición a lo largo del borde');}
   else placement+=range('clampX','Posición X en tablero')+range('clampZ','Posición Z en tablero');
   placement+='<p class="layout-hint">Mueve el anclaje, no la pantalla. Al arrastrar con mordaza se ajusta al borde más cercano. La fijación pasante permite colocarlo en el interior y requiere un taladro o pasacables compatible.</p>';
  }else{
   placement+=range(prefix+'X',item?'Posición X en tablero':'Posición X (lateral)')+range(prefix+'Z',item?'Posición Z en tablero':'Posición Z (fondo)')+range(prefix+'Angle','Giro en planta')+`<div class="rotate-actions"><button data-rotate="-90">↶ −90°</button><button data-rotate="90">+90° ↷</button></div>`;
   placement+=`<p class="layout-hint" ${item?'data-desktop-hint':''}>${item?`Referencia: centro del tablero, que gira con la mesa. X recorre los ${state.deskDepth} cm de fondo; Z los ${state.deskWidth} cm de ancho.`:layoutTarget==='desk'?'Referencia: centro del tablero en el espacio.':'Referencia: centro del extremo trasero del chasis.'} Pulsa <b>Distribuir</b> para arrastrar el elemento en planta.</p>`;
  }
  html+=group('Colocar elementos',picker+placement,item?'Sobre el tablero':'En el espacio');
  if(layoutTarget==='keyboard')html+=group('Tamaño del teclado',range('keyboardWidth','Ancho del teclado')+range('keyboardDepth','Fondo del teclado'));
  if(layoutTarget==='pc')html+=group('Tamaño del PC',range('pcWidth','Ancho de torre')+range('pcDepth','Fondo de torre')+range('pcHeight','Altura de torre'));
  if(layoutTarget==='mouse')html+='<p class="control-hint">Ratón de 12 × 7 cm aprox. Puedes colocarlo y girarlo independientemente del teclado y la alfombrilla.</p>';
  if(layoutTarget==='mat')html+=group('Alfombrilla XL',`<div class="select-control"><label for="matPreset">Medida rápida</label><select id="matPreset"><option value="custom">Personalizada</option><option value="90x40">90 × 40 cm</option><option value="120x60">120 × 60 cm</option><option value="140x80">140 × 80 cm</option></select></div>`+range('matWidth','Ancho de alfombrilla')+range('matDepth','Fondo de alfombrilla'));
  html+=group('Colocación rápida',`<div class="select-control"><label for="layoutPreset">Mesa respecto al cockpit</label><select id="layoutPreset"><option value="free">Personalizada</option><option value="right">Mesa a la derecha</option><option value="left">Mesa a la izquierda</option><option value="front">Mesa enfrente</option></select></div>`);
  html+=group('Flexispot E7 Pro',range('deskH','Altura del tablero'),'Altura desde suelo');
  html+='<button class="arm-edit-action" id="goRoom">Habitación, puertas y muebles ↗</button>';
  html+='<p class="control-hint">Posición y giro de mesa y cockpit independientes. La zona permanece fija al moverlos. El brazo mantiene dos tramos de longitud fija y comprueba su alcance mínimo/máximo y altura VESA. Los giros son en planta; verifica los topes y cargas del modelo real. Diagonal en pulgadas (″), resto en cm. Configura paredes, puertas, ventanas y muebles en la pestaña Habitación.</p>';
 }
 $('#controls').innerHTML=html;
 bindRoomEditor();
 $('#goRoom')?.addEventListener('click',()=>{switchSection('room');setActiveView('top');});
 // Diagonal uses inches rather than world units.
 for(const node of $$('[data-key="monitorInches"]')){const wrap=node.closest('.control');if(wrap){wrap.querySelector('.number-wrap span').textContent='″';wrap.querySelector('.control-range-label span:last-child').textContent='49 ″';node.setAttribute('aria-label','Diagonal de pantalla en pulgadas');}}
 $('#controls').querySelectorAll('input[type=range]').forEach(el=>el.addEventListener('input',()=>{
  const key=el.dataset.key;const val=Number(el.value);el.style.setProperty('--pct',`${(val-Number(el.min))/(Number(el.max)-Number(el.min))*100}%`);$(`#${key}-number`).value=val;update(key,val);
 }));
 $('#controls').querySelectorAll('input[data-number]').forEach(el=>{
  const applyNumber=commit=>{const key=el.dataset.key,[min,max,step]=fieldSpec(key,state);if(el.value.trim()===''||!Number.isFinite(Number(el.value))){if(commit)el.value=state[key];return;}const raw=Number(el.value);if(!commit&&(raw<min||raw>max))return;const val=round(clamp(Math.round(raw/step)*step,min,max));if(commit)el.value=val;const slider=$(`#${key}-range`);slider.value=val;slider.style.setProperty('--pct',`${(val-min)/(max-min)*100}%`);if(state[key]!==val||(['armBaseAngle','armElbowAngle','monitorYaw'].includes(key)&&state.monitorMode!=='manual'))update(key,val);if(commit)el.value=round(controlValue(key),1);};
  el.addEventListener('input',()=>applyNumber(false));el.addEventListener('change',()=>applyNumber(true));el.addEventListener('blur',()=>applyNumber(true));
 });
 $('#controls').querySelectorAll('input[type=checkbox]').forEach(el=>el.addEventListener('change',()=>{update(el.dataset.key,el.checked);}));
 $('#controls').querySelectorAll('select[data-key]').forEach(el=>el.addEventListener('change',()=>{update(el.dataset.key,el.value);if(['clampMount','monitorMode','roomEnabled','roomFullWalls'].includes(el.dataset.key))renderControls();}));
 $('#layoutTargetSelect')?.addEventListener('change',event=>{layoutTarget=event.target.value;renderControls();scene?.setLayoutEditing(layoutEditing,layoutTarget,section==='room');if(desktopTargets.some(t=>t.id===layoutTarget))setActiveView('desk');else if(view==='desk')setActiveView('top');});
 $('#controls').querySelectorAll('[data-rotate]').forEach(button=>button.addEventListener('click',()=>{const key=layoutTarget+'Angle';update(key,(state[key]+Number(button.dataset.rotate)+360)%360);renderControls();}));
 $('#controls').querySelectorAll('[data-monitor-pose]').forEach(button=>button.addEventListener('click',()=>{update('monitorMode',button.dataset.monitorPose);renderControls();setActiveView(button.dataset.monitorPose==='cockpit'?'top':'desk');focusArmControls();toast(button.dataset.monitorPose==='cockpit'?'Monitor orientado hacia el cockpit. Revisa el alcance del brazo.':'Monitor colocado sobre el escritorio.');}));
 $('#armDragBtn')?.addEventListener('click',startArmEditing);
 $('#clampEdgeSelect')?.addEventListener('change',event=>{const edge=event.target.value;state.clampSide=edge;const b=deskBounds(state);if(edge==='xmin'||edge==='xmax')state.clampX=edge==='xmin'?-b.anchorX:b.anchorX;else state.clampZ=edge==='zmin'?-b.anchorZ:b.anchorZ;modified=true;persist();renderControls();refresh();});
 $('#deskSizePreset')?.addEventListener('change',event=>{if(event.target.value==='custom')return;const [width,depth]=event.target.value.split('x').map(Number);state=resizeDesk(state,width,depth);modified=true;persist();renderControls();refresh();setActiveView('desk');toast(`Tablero de ${width} × ${depth} cm aplicado`);});
 $('#matPreset')?.addEventListener('change',event=>{if(event.target.value==='custom')return;const [width,depth]=event.target.value.split('x').map(Number);state=updateDeskItem({...state,matWidth:width},'matDepth',depth);modified=true;persist();renderControls();refresh();});
 $('#layoutPreset')?.addEventListener('change',event=>{if(event.target.value==='free')return;state=layoutPreset(state,event.target.value);modified=true;persist();renderControls();refresh();setActiveView('top');toast('Distribución aplicada. Puedes mover y girar ambos elementos.');});
}
function switchSection(value){section=value;if(value==='desk'&&(layoutTarget.startsWith('feature:')||layoutTarget.startsWith('furniture:')))layoutTarget='desk';if(value==='room'&&(!roomItem(state,layoutTarget)&&!['desk','cockpit'].includes(layoutTarget)))layoutTarget='desk';$$('.config-tabs button').forEach(b=>{const active=b.dataset.section===section;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});$('#controls').setAttribute('aria-labelledby',`tab-${value}`);renderControls();$('#controls').scrollTop=0;scene?.setLayoutEditing(layoutEditing,layoutTarget,section==='room');}
function row(c){return `<div class="check-row ${c.level}"><div class="check-name">${escapeHTML(c.label)}<small>${escapeHTML(c.detail)}</small></div><div class="check-value">${escapeHTML(c.value)}<span class="check-mark">${c.level==='ok'?'✓':c.level==='error'?'×':'!'}</span></div></div>`;}
function refresh(){
 evaluation=evaluate(state);const e=evaluation;
 syncRoomInputs();
 $('#roomInspector').hidden=state.roomEnabled===false;$('#roomSizeTag').textContent=`${state.roomW} × ${state.roomD}`;$('#roomChecks').innerHTML=[...e.extra.filter(c=>c.id==='room'),...e.room.checks].map(row).join('');
 $('#preset').value=state.preset;$('#presetDescription').textContent=presets[state.preset].description;
 $('#sceneTitle').textContent=presets[state.preset].label+(modified?' · ajustado':'');
 $('#desktopChecks').innerHTML=e.desktopChecks.map(row).join('');$('#matTag').textContent=`${state.matWidth} × ${state.matDepth}`;
 $('#deskSizeTag').textContent=`${state.deskWidth} × ${state.deskDepth}`;const sizeSelect=$('#deskSizePreset');if(sizeSelect){const value=`${state.deskWidth}x${state.deskDepth}`;sizeSelect.value=[...sizeSelect.options].some(o=>o.value===value)?value:'custom';}
 $('#controls').querySelectorAll('[data-key]').forEach(el=>{const key=el.dataset.key;if(el.matches('input[type=range]')||el.hasAttribute('data-number')){const [min,max,step]=fieldSpec(key,state);el.min=min;el.max=max;el.step=step;if(el.matches('input[type=range]')){el.value=controlValue(key);el.style.setProperty('--pct',`${(controlValue(key)-min)/(max-min)*100}%`);const labels=el.closest('.control').querySelectorAll('.control-range-label span');labels[0].textContent=min;labels[1].textContent=`${max} ${unitFor(key)}`;}else if(el!==document.activeElement)el.value=round(controlValue(key),1);}});

 const mode=$('#monitorMode');if(mode)mode.value=state.monitorMode;
 const bend=$('#armBend');if(bend)bend.value=state.armBend;
 const lengths=$('#armLengths');if(lengths)lengths.textContent=`Primer tramo: ${round(e.armPose.first)} cm · segundo tramo: ${round(e.armPose.second)} cm. El codo a 0° deja el brazo estirado; ±180° lo pliega.`;
 const coordinateHint=$('[data-desktop-hint]');if(coordinateHint)coordinateHint.innerHTML=`Referencia: centro del tablero, que gira con la mesa. X recorre los ${state.deskDepth} cm de fondo; Z los ${state.deskWidth} cm de ancho. Pulsa <b>Distribuir</b> para arrastrar el elemento en planta.`;
 $('#heightTag').textContent=`${state.height} cm`;
 $('#ergonomics').innerHTML=e.bodyCheck.map(row).join('');$('#spaceChecks').innerHTML=[...e.spaceCheck,...e.extra.filter(c=>c.id!=='room'&&c.level!=='ok')].map(row).join('');
 const banner=$('#validationBanner');banner.className=`validation-banner ${e.errors?'error':e.warnings?'warning':''}`;
 banner.innerHTML=`<span class="status-icon">${e.errors?'×':e.warnings?'!':'✓'}</span><div><strong>${e.errors?`${e.errors} ajuste${e.errors>1?'s':''} pendiente${e.errors>1?'s':''}`:e.warnings?`${e.warnings} detalle${e.warnings>1?'s':''} por revisar`:'Buen punto de partida'}</strong><small>${e.errors?'Consulta las comprobaciones de abajo.':'Valida la postura con tu equipo real.'}</small></div>`;
 $('#reachValue').textContent=`${Math.round(e.reach)} / ${state.armReach} cm`;
 $('#reachMax').textContent=`Máx. ${state.armReach} cm`;$('#reachMeter').style.width=`${Math.min(100,e.reach/state.armReach*100)}%`;$('#reachMeter').classList.toggle('over',e.reach>state.armReach);
 $('#metricFootprint').innerHTML=`${state.length} <small>×</small> ${state.width} <small>cm</small>`;
 $('#metricWidthNote').textContent=`${Math.ceil(e.rigRight-e.rigLeft)} cm con accesorios`;
 $('#metricSpace').innerHTML=`${Math.ceil(e.spaceW)} <small>×</small> ${Math.ceil(e.spaceD)} <small>cm</small>`;
 $('#metricProfiles').innerHTML=`${(e.totalMm/1000).toLocaleString('es-ES',{maximumFractionDigits:2})} <small>m</small>`;$('#metricPieces').textContent=`${e.cuts} cortes · serie 40`;
 scene?.update(state,evaluation);
}
function download(filename,text,type){const blob=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function exportConfig(){download('cockpit-lab-configuracion.json',JSON.stringify({app:'Cockpit Lab',version:1,config:state},null,2),'application/json');toast('Configuración descargada. Puedes cargarla desde el resumen.');}
function summary(){
 const e=evaluation,s=state;
 const fmt=v=>v.toLocaleString('es-ES',{maximumFractionDigits:2});
 const dims=[['Preset',presets[s.preset].label],['Estatura de referencia',`${s.height} cm`],['Chasis exterior',`${s.length} × ${s.width} cm`],['Ancho con accesorios',`${Math.ceil(e.rigRight-e.rigLeft)} cm`],['Asiento · posición / altura',`${s.seatZ} / ${s.seatH} cm`],['Respaldo desde vertical',`${s.recline}°`],['Volante · posición / centro',s.wheel?`${s.wheelZ} / ${s.wheelH} cm · ${s.wheelTilt}°`:'Desactivado'],['Pedalera · posición / altura',`${s.pedalZ} / ${s.pedalH} cm · ${s.pedalTilt}°`],['Mandos laterales · pos. / altura',s.hotas||s.shifter||s.handbrake?`${s.hotasZ} / ${s.hotasH} cm · salida ${s.hotasOut}`:'Desactivados'],['Cambio y freno · lado',s.shifter||s.handbrake?(s.drivingSide==='left'?'Izquierda del piloto':'Derecha del piloto'):'Desactivados'],['Joystick central · pos. / altura',s.centerStick?`${s.stickZ} / ${s.stickH} cm`:'Desactivado'],['Mesa · tablero / altura',`${s.deskWidth} × ${s.deskDepth} / ${s.deskH} cm`],['Mesa · posición X / Z',`${s.deskX} / ${s.deskZ} cm`],['Mesa · giro en planta',`${s.deskAngle}°`],['Cockpit · posición X / Z',`${s.cockpitX} / ${s.cockpitZ} cm`],['Cockpit · giro en planta',`${s.cockpitAngle}°`],['Habitación · ancho / fondo / alto',`${s.roomW} / ${s.roomD} / ${s.roomH} cm`],['Habitación · origen X / Z',`${s.roomX} / ${s.roomZ} cm`],['Monitor · diagonal / altura',`${s.monitorInches}″ / ${s.monitorH} cm`],['Monitor · modo',({cockpit:'Cockpit',desk:'Escritorio',vr:'VR · aparcado',manual:'Articulaciones manuales'})[s.monitorMode]],['Anclaje · X / Z en tablero',`${s.clampX} / ${s.clampZ} cm`],['Anclaje · fijación',s.clampMount==='grommet'?'Pasante':'Mordaza'],['Brazo · necesario / declarado',`${Math.round(e.reach)} / ${s.armReach} cm`],['Brazo · tramos base / terminal',`${round(e.armPose.first)} / ${round(e.armPose.second)} cm`],['Brazo · base / codo / VESA',`${round(e.armPose.baseAngle)}° / ${round(e.armPose.elbowAngle)}° / ${round(wrapAngle(e.monitorAngle-s.deskAngle))}°`],['Zona libre / paso deseado',`${s.roomW} × ${s.roomD} / ${s.aisle} cm`]];
 $('#summaryContent').innerHTML=`<div class="summary-inner"><div class="summary-stats"><div><small>Chasis exterior</small><b>${s.length} × ${s.width} cm</b></div><div><small>Conjunto sin paso</small><b>${Math.ceil(e.spaceW)} × ${Math.ceil(e.spaceD)} cm</b></div><div><small>Perfil neto / +10 % compra</small><b>${fmt(e.totalMm/1000)} / ${fmt(e.totalMm/1000*1.1)} m</b></div><div><small>Cortes de aluminio</small><b>${e.cuts} piezas</b></div></div><h3 class="summary-title">Geometría de tu configuración<span>Alturas desde suelo · posiciones desde atrás</span></h3><div class="summary-dims">${dims.map(([n,v])=>`<p>${n}<b>${v}</b></p>`).join('')}</div>${roomSummary(s)}<h3 class="summary-title">Sobre el escritorio<span>Coordenadas desde el centro del tablero</span></h3><table class="summary-table"><thead><tr><th>Elemento</th><th>Huella X × Z (cm)</th><th>Posición X / Z (cm)</th><th>Giro</th></tr></thead><tbody>${e.desktopItems.map(i=>`<tr><td>${i.label}</td><td>${i.sizeX} × ${i.sizeZ}${i.id==='pc'?` · h ${s.pcHeight}`:''}</td><td>${i.local.x} / ${i.local.z}</td><td>${i.local.angle}°</td></tr>`).join('')}</tbody></table><h3 class="summary-title">Comprobaciones<span>${e.errors} pendientes · ${e.warnings} avisos</span></h3><div class="summary-checks">${e.checks.map(c=>`<p>${c.level==='ok'?'✓':c.level==='error'?'×':'!'} ${escapeHTML(c.label)}: <b>${escapeHTML(c.value)}</b> — ${escapeHTML(c.detail)}</p>`).join('')}</div><h3 class="summary-title">Lista de cortes orientativa<span>Longitudes netas · sin ancho de sierra</span></h3><table class="summary-table"><thead><tr><th>Pieza</th><th>Perfil (mm)</th><th>Ud.</th><th>Largo (mm)</th><th>Total (mm)</th></tr></thead><tbody>${e.parts.map(p=>`<tr><td>${p.name}</td><td>${p.profile}</td><td>${p.qty}</td><td>${p.mm}</td><td>${p.total}</td></tr>`).join('')}</tbody></table><h3 class="summary-title">Piezas y fijaciones<span>Cantidades preliminares</span></h3><table class="summary-table"><thead><tr><th>Componente</th><th>Detalle</th><th>Ud.</th></tr></thead><tbody>${e.accessories.map(p=>`<tr><td>${p.name}</td><td>${p.note}</td><td>${p.qty}</td></tr>`).join('')}</tbody></table><div class="summary-note"><b>Antes de pedir o cortar:</b> el despiece supone largueros exteriores y travesaños entre caras interiores (ancho − 80 mm), base a 100 mm sobre suelo y módulos sobre escuadras. La altura de cojín es una medida corporal objetivo: adapta los apoyos al espesor y raíles de tu asiento. Las placas se modelan como envolventes, sin taladros. Añade margen de corte y verifica ranura, escuadras, espesor de placas, anclajes y carga con el proveedor. No es un cálculo estructural ni un plano de fabricación validado. Los perfiles 40 × 80 convencionales no se telescopan entre sí. El brazo usa dos tramos de longitud fija con giros horizontales; verifica VESA, peso, topes de giro y recorrido reales.</div></div>`;
 $('#summaryDialog').showModal();
}
$$('.config-tabs button').forEach(b=>b.addEventListener('click',()=>{switchSection(b.dataset.section);if(b.dataset.section==='room'){layoutEditing=true;$('#layoutBtn').classList.add('active');$('#layoutBtn').setAttribute('aria-pressed','true');scene?.setLayoutEditing(true,layoutTarget,true);setActiveView('top');}}));
$('.config-tabs').addEventListener('keydown',event=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const tabs=$$('.config-tabs button'),i=tabs.findIndex(t=>t.dataset.section===section),next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(i+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;switchSection(tabs[next].dataset.section);tabs[next].focus();}});
$('#preset').addEventListener('change',()=>{const key=$('#preset').value;state={...state,...presets[key].values,preset:key};modified=false;persist();renderControls();refresh();toast(`Preset ${presets[key].label} aplicado`);});
$('#resetBtn').addEventListener('click',()=>{state={...defaults};modified=false;persist();renderControls();refresh();scene?.setView(view);toast('Configuración inicial restaurada');});
function setActiveView(next){view=next;$$('[data-view]').forEach(t=>t.classList.toggle('active',t.dataset.view===view));scene?.setView(view);$('.viewport-note span').textContent=view==='iso'?'Arrastra para girar · rueda para acercar':['top','desk'].includes(view)&&layoutEditing?layoutTarget==='arm'?'Arrastra CODO o VESA · anclaje sobre el tablero':'Arrastra un elemento · selecciona y gira en '+(section==='room'?'Habitación':'Mesa'):'Rueda para acercar · arrastra para desplazar';}
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>setActiveView(b.dataset.view)));
$('#layoutBtn').addEventListener('click',()=>{layoutEditing=!layoutEditing;$('#layoutBtn').classList.toggle('active',layoutEditing);$('#layoutBtn').setAttribute('aria-pressed',String(layoutEditing));scene?.setLayoutEditing(layoutEditing,layoutTarget,section==='room');if(layoutEditing){switchSection(section==='room'?'room':'desk');setActiveView(desktopTargets.some(t=>t.id===layoutTarget)?'desk':'top');}else setActiveView(view);});
$('#dimensionBtn').addEventListener('click',()=>{const on=$('#dimensionBtn').getAttribute('aria-pressed')!=='true';$('#dimensionBtn').setAttribute('aria-pressed',String(on));$('#dimensionBtn').setAttribute('aria-label',on?'Ocultar cotas':'Mostrar cotas');$('#dimensionBtn').classList.toggle('active',on);scene?.setDimensions(on);});
$('#personBtn').addEventListener('click',()=>{const on=$('#personBtn').getAttribute('aria-pressed')!=='true';$('#personBtn').setAttribute('aria-pressed',String(on));$('#personBtn').setAttribute('aria-label',on?'Ocultar piloto':'Mostrar piloto');$('#personBtn').classList.toggle('active',on);scene?.setPerson(on);});
$('#fitBtn').addEventListener('click',()=>scene?.setView(view));
function focusArmControls(){const panel=$('#controls'),arm=$('#armControls');if(arm)panel.scrollTop+=arm.getBoundingClientRect().top-panel.getBoundingClientRect().top;}
function startArmEditing(){layoutTarget='arm';layoutEditing=true;$('#layoutBtn').classList.add('active');$('#layoutBtn').setAttribute('aria-pressed','true');switchSection('desk');scene?.setLayoutEditing(true,'arm');setActiveView('top');focusArmControls();toast('Arrastra CODO o VESA; también puedes usar sus controles de giro.');}
$('#editArmBtn').addEventListener('click',startArmEditing);
$('#adjustRoom').addEventListener('click',()=>{$('#tab-room').click();$('.config-panel').scrollIntoView({behavior:'smooth',block:'nearest'});});
$('#adjustBody').addEventListener('click',()=>{switchSection('body');$('.config-panel').scrollIntoView({behavior:'smooth',block:'nearest'});});
$('#adjustDesk').addEventListener('click',()=>{switchSection('desk');$('.config-panel').scrollIntoView({behavior:'smooth',block:'nearest'});});
$('#adjustDesktop').addEventListener('click',()=>{layoutTarget='arm';switchSection('desk');$('.config-panel').scrollIntoView({behavior:'smooth',block:'nearest'});scene?.setLayoutEditing(layoutEditing,layoutTarget,section==='room');setActiveView('desk');});
$('#helpBtn').addEventListener('click',()=>$('#helpDialog').showModal());
['openSummary','partsBtn'].forEach(id=>$(`#${id}`).addEventListener('click',summary));
$$('[data-close]').forEach(b=>b.addEventListener('click',()=>$(`#${b.dataset.close}`).close()));
$$('dialog').forEach(d=>d.addEventListener('click',ev=>{if(ev.target===d){const r=d.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)d.close();}}));
$('#saveConfig').addEventListener('click',exportConfig);
$('#csvBtn').addEventListener('click',()=>{const esc=v=>`"${String(v).replaceAll('"','""')}"`,rows=[['Pieza','Perfil (mm)','Cantidad','Longitud neta (mm)','Longitud total (mm)','Detalle'],...evaluation.parts.map(p=>[p.name,p.profile,p.qty,p.mm,p.total,'Verificar antes de fabricar']),[],['Piezas y fijaciones','', 'Cantidad','','','Detalle'],...evaluation.accessories.map(p=>[p.name,'',p.qty,'','',p.note])];download('cockpit-lab-lista-cortes.csv','\ufeff'+rows.map(r=>r.map(esc).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Lista de cortes descargada');});
$('#printBtn').addEventListener('click',()=>window.print());
$('#importBtn').addEventListener('click',()=>$('#importFile').click());
$('#importFile').addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file)return;try{if(file.size>100000)throw new Error('Archivo demasiado grande');const data=JSON.parse(await file.text());if(data.app!=='Cockpit Lab'||data.version!==1)throw new Error('Formato no compatible');state=sanitize(data.config);modified=true;persist();renderControls();refresh();$('#summaryDialog').close();toast('Configuración cargada');}catch{toast('No se pudo cargar: usa un JSON exportado por Cockpit Lab.');}event.target.value='';});
window.addEventListener('pagehide',()=>{clearTimeout(pendingSave);persist();});
renderControls();refresh();
try{scene=new CockpitScene($('#viewport'),$('#sceneLabels'));scene.update(state,evaluation);scene.setView('iso');scene.onArmMove=(joint,x,z)=>{state=moveArmJoint(state,joint,x,z);modified=true;clearTimeout(pendingSave);pendingSave=setTimeout(persist,250);refresh();};scene.onLayoutSelect=target=>{layoutTarget=target;if(section==='desk'||section==='room')renderControls();scene.setLayoutEditing(layoutEditing,layoutTarget,section==='room');};scene.onLayoutMove=(target,x,z)=>{const item=desktopTargets.find(t=>t.id===target),previousEdge=clampEdge(state);if(target.startsWith('feature:')||target.startsWith('furniture:'))state=moveRoomTarget(state,target,x,z);else if(item)state=placeDeskItem(state,target,x,z);else{state[target+'X']=round(clamp(x,-1500,1500));state[target+'Z']=round(clamp(z,-1500,1500));}modified=true;clearTimeout(pendingSave);pendingSave=setTimeout(persist,250);if(target==='arm'&&previousEdge!==clampEdge(state)&&section==='desk')renderControls();refresh();};}catch(error){console.error(error);$('#webglFallback').hidden=false;}
// Read-only view of current calculations, useful for verifying a configuration.
window.cockpitLab={getState:()=>structuredClone(state),getEvaluation:()=>structuredClone(evaluation)};
